validator:
function validate(input) {
  const [{ Person = [] }] = input;
  const ids = new Set();
  for (const [id, email] of Person) {
    if (id === null) return 'Every row needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Person.`;
    if (email === null) return `Row ${id} needs an email.`;
    if (email !== email.toLowerCase()) return `Email ${email} has uppercase letters.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  // A small address pool makes repeats common; ids are shuffled so the smallest id is not always inserted first.
  const pool = small ? ['john@example.com', 'bob@example.com', 'ana@leetcode.com', 'kim@mail.org'] : Array.from({ length: 600 }, (_, i) => `user${i}@example.com`);
  const ids = Array.from({ length: small ? 20 : count }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Person = [];
  for (let i = 0; i < count; i++) Person.push([ids[i], pool[Math.floor(rand() * pool.length)]]);
  return [{ Person }];
}
